const OPEN_APP = icon('M13.5 11.25L9 6.75L4.5 11.25');
const NOTIFICATIONS = icon(`M7.0156 15.75C7.5445 16.2168 8.2392 16.5 9 16.5
  C9.7608 16.5 10.4555 16.2168 10.9844 15.75M13.5 6
  C13.5 4.8065 13.0259 3.6619 12.182 2.818C11.3381 1.9741 10.1935 1.5 9 1.5
  C7.8065 1.5 6.6619 1.9741 5.818 2.818C4.9741 3.6619 4.5 4.8065 4.5 6
  C4.5 8.3176 3.9153 9.9045 3.2622 10.9541C2.7113 11.8394 2.4359 12.2821 2.446 12.4056
  C2.4572 12.5423 2.4861 12.5944 2.5963 12.6762C2.6958 12.75 3.1444 12.75 4.0416 12.75
  H13.9583C14.8555 12.75 15.3041 12.75 15.4037 12.6762
  C15.5138 12.5944 15.5428 12.5423 15.554 12.4056
  C15.5641 12.2821 15.2886 11.8394 14.7377 10.9541
  C14.0846 9.9045 13.5 8.3176 13.5 6Z`);

export function createMinduckPanels({ onAction, onFocus, onReleaseFocus } = {}) {
  const stack = document.createElement('div');
  stack.className = 'minduck-outputs';
  stack.setAttribute('role', 'region');
  stack.setAttribute('aria-label', 'Matter 活动会话');
  stack.hidden = true;
  const outputs = new Map();
  const views = new Map(), runningViews = new Map(), dismissed = new Set();
  let latestTasks = [], queueKeys = [];
  const layers = [1, 2].map(depth => {
    const layer = document.createElement('div');
    layer.className = 'minduck-panel minduck-stack-layer';
    layer.style.setProperty('--stack-depth', depth);
    layer.setAttribute('aria-hidden', 'true');
    layer.hidden = true;
    stack.appendChild(layer);
    return layer;
  });
  const messageKey = task => [task.conversationId || 'current', task.turnId || '',
    task.qa ? task.qa.contextId + ':' + task.qa.itemId : task.status || 'active'].join(':');
  function card(id) {
    if (outputs.has(id)) return outputs.get(id);
    const output = document.createElement('section');
    output.className = 'minduck-panel minduck-output';
    output.dataset.conversationId = id;
    output.setAttribute('role', 'group');
    output.innerHTML = '<div class="minduck-content"><button type="button" class="minduck-message"><span class="minduck-output-line"></span><span class="minduck-output-line secondary"></span></button><div class="minduck-running" hidden></div><div class="minduck-qa" hidden></div></div><button type="button" class="minduck-close" aria-label="关闭这条桌宠消息" title="关闭这条消息">×</button>';
    const message = output.querySelector('.minduck-message');
    message.addEventListener('click', async () => {
      try { await onAction?.('open-conversation', { conversationId: output.dataset.conversationId,
        turnId: output.dataset.turnId || '' }); }
      catch (error) { console.error('无法打开 Matter 会话:', error); }
    });
    output.querySelector('.minduck-close').addEventListener('click', event => {
      event.stopPropagation();
      dismissed.add(output.dataset.messageKey);
      if (dismissed.size > 200) dismissed.delete(dismissed.values().next().value);
      onReleaseFocus?.();
      setOutputs(latestTasks);
    });
    outputs.set(id, output);
    stack.appendChild(output);
    return output;
  }

  const actions = document.createElement('div');
  actions.className = 'minduck-panel minduck-actions';
  actions.setAttribute('role', 'group');
  actions.setAttribute('aria-label', 'Matter 快捷操作');
  actions.hidden = true;
  let composing = false, composerBusy = false, quickView;
  function closeComposer() {
    composing = false;
    actions.classList.remove('is-composing');
    quickView.update(false);
    onReleaseFocus?.();
  }
  function openComposer() {
    composing = true;
    actions.classList.add('is-composing');
    quickView.update(true);
    onFocus?.();
  }
  for (const [id, label, svg] of [['new-chat', '和 Matter 聊天', NEW_CHAT], ['open-app', '打开 Minduck Matter', OPEN_APP]]) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'minduck-action';
    button.dataset.action = id;
    button.setAttribute('aria-label', label);
    button.disabled = typeof onAction !== 'function';
    button.setAttribute('aria-disabled', String(button.disabled));
    button.title = label;
    button.addEventListener('click', async () => {
      if (id === 'new-chat') { openComposer(); return; }
      try { await onAction?.(id); }
      catch (error) { console.error('无法打开 Matter 客户端:', error); }
    });
    button.innerHTML = svg;
    actions.appendChild(button);
  }
  const quick = document.createElement('div');
  quick.className = 'minduck-quick';
  quick.setAttribute('aria-label', '和 Matter 聊天');
  actions.appendChild(quick);
  quickView = createQuickChatView(quick, qaStyles, { onAction, onClose:closeComposer,
    onBusy:busy => { composerBusy = busy; } });
  quickView.update(false);
  window.addEventListener('blur', () => { if (composing && !composerBusy) closeComposer(); });
  const appButton = actions.querySelector('[data-action="open-app"]');
  const appIcon = document.createElement('span');
  appIcon.className = 'minduck-action-icon';
  appIcon.innerHTML = OPEN_APP;
  const badge = document.createElement('span');
  badge.className = 'minduck-notification-badge';
  badge.setAttribute('aria-hidden', 'true');
  badge.hidden = true;
  appButton.replaceChildren(appIcon, badge);
  let notificationCount = 0;
  function setNotificationCount(value = 0) {
    const count = Number.isSafeInteger(value) ? Math.min(99999, Math.max(0, value)) : 0;
    if (count === notificationCount) return;
    notificationCount = count;
    appIcon.innerHTML = count ? NOTIFICATIONS : OPEN_APP;
    badge.hidden = !count;
    badge.textContent = count > 99 ? '99+' : count ? String(count) : '';
    const label = '打开 Minduck Matter' + (count ? `，${count} 个会话通知` : '');
    appButton.setAttribute('aria-label', label);
    appButton.title = label;
  }

  const handle = document.createElement('button');
  handle.type = 'button';
  handle.className = 'minduck-handle';
  handle.setAttribute('aria-label', '展开 Matter 快捷操作');
  handle.hidden = true;
  const expand = () => {
    actions.hidden = false;
    handle.hidden = true;
    actions.firstElementChild.focus({ preventScroll: true });
  };
  handle.addEventListener('focus', expand);
  handle.addEventListener('click', expand);
  document.body.append(stack, actions, handle);

  let taskActive = false, bodyBox = null, scale = 1;
  function setScale(value = 1) {
    scale = Number.isFinite(value) ? clamp(value, .8, 1.5) : 1;
    for (const element of [stack, actions, handle]) element.style.setProperty('--minduck-panel-scale', scale);
  }
  function setOutput(text = '', detail = '', active) {
    setOutputs([{ text, detail, active: active ?? Boolean(String(text).trim() || String(detail).trim()) }]);
  }
  function setOutputs(tasks = []) {
    latestTasks = tasks;
    const seen = new Set();
    const available = tasks.filter(task => {
      const key = messageKey(task);
      const id = task.conversationId || 'current';
      if (!task.active || dismissed.has(key) || seen.has(id)) return false;
      seen.add(id); return true;
    });
    const byKey = new Map(available.map(task => [task.conversationId || 'current', task]));
    queueKeys = [...queueKeys.filter(key => byKey.has(key)),
      ...[...byKey.keys()].filter(key => !queueKeys.includes(key))];
    const queued = queueKeys.map(key => byKey.get(key));
    const active = queued.slice(0, 1);
    const depth = Math.min(2, Math.max(0, queued.length - 1));
    stack.style.setProperty('--stack-offset', `${depth * 6}px`);
    stack.dataset.messageCount = String(queued.length);
    stack.setAttribute('aria-label', `Matter 活动会话，${queued.length} 条消息待处理`);
    layers.forEach((layer, index) => { layer.hidden = index >= depth; });
    taskActive = active.length > 0;
    const ids = new Set(active.map(task => task.conversationId || 'current'));
    for (const [id, output] of outputs) if (!ids.has(id)) {
      views.get(id)?.destroy(); views.delete(id);
      runningViews.get(id)?.destroy(); runningViews.delete(id); output.remove(); outputs.delete(id);
    }
    for (const task of active) {
      const id = task.conversationId || 'current';
      const output = card(id);
      output.dataset.turnId = task.turnId || '';
      output.dataset.messageKey = messageKey(task);
      const message = output.querySelector('.minduck-message'), question = output.querySelector('.minduck-qa');
      message.disabled = !task.conversationId || typeof onAction !== 'function';
      output.setAttribute('aria-label', `打开会话：${task.detail || task.text || '当前任务'}`);
      const rows = [String(task.text || '').replace(/\s+/gu, ' ').trim(), String(task.detail || '').replace(/\s+/gu, ' ').trim()];
      if (!rows.some(Boolean)) rows[0] = '任务进行中';
      message.querySelectorAll('.minduck-output-line').forEach((line, index) => { line.textContent = rows[index]; });
      message.title = rows.filter(Boolean).join('\n');
      const running = output.querySelector('.minduck-running');
      const isRunning = task.status === 'running' && !task.qa;
      message.hidden = !!task.qa || isRunning;
      running.hidden = !isRunning;
      question.hidden = !task.qa;
      output.classList.toggle('has-qa', !!task.qa);
      if (task.qa) {
        if (!views.has(id)) views.set(id, createQaView(question, qaStyles, { onAction, onFocus }));
        views.get(id).update(task);
      }
      if (isRunning) {
        if (!runningViews.has(id)) runningViews.set(id, createRunningView(running, qaStyles, { onAction, onFocus, onReleaseFocus }));
        runningViews.get(id).update(task);
      } else runningViews.get(id)?.update(null);
      output.hidden = false;
    }
    // Retain an empty hidden status node for accessibility and legacy preview callers.
    if (!taskActive) { card('current').hidden = true; stack.hidden = true; }
  }

  function overStack(point) {
    if (!point || stack.hidden) return false;
    const rect = stack.getBoundingClientRect();
    return point.x >= rect.left && point.x <= rect.right && point.y >= rect.top && point.y <= rect.bottom;
  }

  function overActions(point) {
    if (!point || actions.hidden || !bodyBox) return false;
    const rect = actions.getBoundingClientRect();
    const notes = composing && quick.shadowRoot.querySelector('.pet-quick-notes');
    if (notes) {
      const r = notes.getBoundingClientRect();
      if (point.x >= r.left && point.x <= r.right && point.y >= r.top && point.y <= r.bottom) return true;
    }
    // Once revealed, the figure's full extent and both buttons form one continuous hover area.
    // The same area owns native mouse input, including transparent corners and the connecting gap.
    return point.x >= Math.min(bodyBox.x, rect.left) - 12 * scale
      && point.x <= Math.max(bodyBox.x + bodyBox.w, rect.right) + 12 * scale
      && point.y >= Math.min(bodyBox.y, rect.top) - 12 * scale
      && point.y <= Math.max(bodyBox.y + bodyBox.h, rect.bottom) + 12 * scale;
  }

  function overHandle(point) {
    if (!point || handle.hidden) return false;
    const rect = handle.getBoundingClientRect();
    return point.x >= rect.left && point.x <= rect.right && point.y >= rect.top && point.y <= rect.bottom;
  }

  function position(element, center, top) {
    // offsetWidth/Height round fractional CSS pixels and can push scaled panels past an edge.
    const style = getComputedStyle(element);
    const width = parseFloat(style.width) * scale, height = parseFloat(style.height) * scale;
    const left = clamp(center - width / 2, 16, Math.max(16, innerWidth - width - 16));
    const y = clamp(top, 16, Math.max(16, innerHeight - height - 16));
    element.style.transform = `translate3d(${left.toFixed(2)}px, ${y.toFixed(2)}px, 0) scale(${scale})`;
  }

  setOutput();
  return {
    surfaces: [stack, actions, handle],
    // The 6px handle and 42px capsule share their top edge, 6px below the body.
    get floorGap() { return 64 * scale; },
    setScale,
    setOutput,
    setOutputs,
    setNotificationCount,
    hit: (point) => overActions(point) || overHandle(point) || overStack(point),
    layout(body, { conversationOpen = false, pointer = null, hoveringBody = false } = {}) {
      const box = body?.box;
      bodyBox = box ?? null;
      const manipulating = body?.pressing || ['drag', 'air', 'land'].includes(body?.mode);
      stack.hidden = !box || !taskActive || conversationOpen;
      for (const output of outputs.values()) output.hidden = stack.hidden;
      const hovered = box && (composing || hoveringBody || overActions(pointer) || overHandle(pointer)
        || actions.querySelector(':focus-visible'));
      actions.hidden = !box || manipulating || !hovered;
      handle.hidden = !box || manipulating || !actions.hidden;
      if (!box) return;
      const center = box.x + box.w / 2;
      if (!stack.hidden) {
        const bottom = Math.max(80 * scale, Math.min(box.y, body.bubble.y) - 16 * scale);
        const offset = Number.parseFloat(stack.style.getPropertyValue('--stack-offset')) || 0;
        stack.style.maxHeight = `${(bottom - 16) / scale}px`;
        for (const output of outputs.values()) output.style.maxHeight = `${(bottom - 16) / scale - offset}px`;
        position(stack, center, bottom - parseFloat(getComputedStyle(stack).height) * scale);
      }
      // Reserve the expanded height for both states, including at a display's bottom edge.
      const controlsTop = clamp(box.y + box.h + 6 * scale, 16, Math.max(16, innerHeight - 42 * scale - 16));
      if (!actions.hidden) position(actions, center, controlsTop);
      if (!handle.hidden) position(handle, center, controlsTop);
    },
  };
}
